INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61975892', 61975892, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Jasa Alih Daya Keamanan di Kawasan BRIN Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota) | Jawa Barat, Bogor (Kab.) | LAINNYA, Lainnya', 99900000000, 'November 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '1', 'RUANG LINGKUP PEKERJAAN Penyedia jasa alih daya tenaga keamanan bertanggung jawab penuh atas seluruh tahapan penyediaan layanan keamanan di seluruh lingkungan kerja yang berada dalam area kawasan BRIN meliputi: Menyediakan tenaga kerja keamanan Mengelola operasional tenaga kerja keamanan Membuat dan memastikan tenaga keamanan memenuhi prosedur kerja Memenuhi SLA yang ditetapkan sesuai yang tertulis di KAK', 'SPESIFIKASI TEKNIS Syarat Teknis Penyedia Mampu menyediakan tenaga kerja keamanan yang menjaga keamanan selama 24 jam yang terdiri dari Kepala Satpam, Wakil Kepala Satpam, komandan regu serta pelaksana keamanan yang dibuktikan dengan dokumen penjelasan metode pelaksanaan pekerjaan jasa keamanan Memiliki kinerja baik dalam pekerjaan pengelolaan alih daya tenaga keamanan selama 3 tahun minimal 3 pemberi kerja dengan nilai kontrak senilai 50M hingga 100M selama 3 tahun terakhir dibuktikan dengan melampirkan surat referensi kinerja baik dan bukti kontrak dengan pemberi kerja Memiliki kantor atau jaringan dan pengalaman di wilayah kawasan BRIN yang dibuktikan dengan surat keterangan domisili dari kecamatan/kelurahan dan bukti sewa atau sertifikat kepemilikan tempat yang menjadi lokasi kantor ; Memiliki surat ijin operasional penyedia jasa tenaga keamanan dari instansi yang berwenang; Memberikan surat pernyataan Kepemilikan alat-alat tenaga keamanan, atas barang yang ditawarkan dan foto-foto alat tersebut. Wajib memiliki dan menggunakan peralatan/sarana prasarana minimal yaitu: HT (radio komunikasi) Metal detector Senter Mirror inspection Tongkat pengatur lalu lintas Papan stop Night vision Mobil patroli untuk Kawasan KST B.J. Habibie Serpong dan KST Soekarno Cibinong Memiliki sertifikat kepesertaan jaminan sosial tenaga kerja (BPJS Ketenagakerjaan) yang masih berlaku dan dikeluarkan oleh instansi yang berwenang; Memiliki Sertifikat Manajemen Mutu ISO 9001-2015 dan Sistem Manajemen Kesehatan dan Keselamatan Kerja ISO 45001:2018/SMK3/OHSAS 18001. Menyampaikan jadwal atau timeline penanganan selama masa transisi Menyampaikan strategi operasional selama masa transisi Menyampaikan proses rekruitment pegawai; Wajib menggunakan aplikasi/sistem informasi guna mengontrol pelaksanaan keamanan yang dilakukan. Aplikasi memiliki fitur minimal sistem kontrol patroli berbasis QR Code, dashboard yang memberikan informasi bagi BRIN, dan sistem absensi berbasis lokasi bagi tenaga keamanan. Persyaratan Teknis Tenaga Kepala Satpam, Wakil Kepala Satpam dan Komandan Regu Kepala dan Komandan Regu yang harus dimiliki oleh Perusahaan Penyedia Jasa adalah: Kepala Satpam Memiliki sertifikat keahlian Gada Utama yang dikeluarkan dari Kepolisian Republik Indonesia Berpengalaman profesional sebagai tenaga keamanan minimal 5 tahun Memiliki Sertifikasi Pelatihan Pengamanan Objek Vital Nasional (untuk yang ditempatkan di 8 lokasi obvitnas) - dalam minimal 6 bulan wajib memiliki sertifikasi tersebut) Wakil Kepala Satpam Memiliki sertifikat keahlian minimal Gada Madya yang dikeluarkan dari Kepolisian Republik Indonesia Berpengalaman profesional sebagai tenaga keamanan minimal 5 tahun Komandan Regu Memiliki sertifikat keahlian Gada Madya yang dikeluarkan dari Kepolisian Republik Indonesia Berpengalaman profesional sebagai tenaga keamanan minimal 3 tahun. Pelaksana Keamanan Kawasan Nukli Memiliki Sertifikat keahlian Gada Pratama yang dikeluarkan dari Kepolisian Republik Indonesia Memiliki Sertifikat Keamanan Instalasi Nuklir Memiliki Sertifikat Dasar Radiasi Memiliki Sertifikat Proteksi Kebakaran Pelaksana Keamanan Persyaratan teknis tenaga pelaksana keamanan secara penuh/full time adalah: Pendidikan sekurang-kurangnya lulusan SLTA/ Sederajat; Memiliki Sertifikat Gada Pratama yang dikeluarkan dari Kepolisian Republik Indonesia; Berpengalaman profesional sebagai tenaga keamanan minimal 2 tahun; Berbadan sehat yang dibuktikan dengan surat keterangan dokter; Bersikap sopan, jujur, rajin, dapat bekerjasama, memiliki etos kerja yang baik dan tidak menggunakan narkoba; Berpenampilan rapi, bersih, tidak bertato dan menggunakan seragam sesuai ketentuan; Mampu berkomunikasi dan mempunyai semangat kerja tinggi; Siap bekerja shift termasuk pada saat penyelenggaraan event atau acara lainnya; Mentaati semua aturan yang ditetapkan oleh BRIN; Memahami dan mahir dalam penggunaan peralatan keamanan seperti drill tongkat dan drill borgol dan perlengkapan keamanan lainnya. Bersedia melaksanakan tugas lainnya sesuai arahan pimpinan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 2, 83728);
