INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62797792', 62797792, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Individual Penyusunan Kajian Strategi Pengawalan Pertumbuhan Ekonomi Daerah Direktorat Pemerintahan, Keuangan Daerah, Dan Transfer Ke Daerah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99990000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Merupakan Tenaga Ahli dalam negeri (Dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk). 2. Memiliki NPWP dan status valid Konfirmasi Status Wajib Pajak (KSWP). 3. Memiliki pendidikan minimal Strata Satu (S1) di bidang Perencanaan Wilayah dan Kota/Teknik Planologi/Studi Pembangunan atau bidang lain yang relevan, dibuktikan dengan ijazah dan transkrip nilai. 4. Memiliki pengalaman atau pernah tergabung dalam pengelolaan data dibuktikan dengan laporan atau screenshot sistematika pengelolaan data yang disusun. 5. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman sub kontrak. 6. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan).', '1. Perumusan konsep dan latar belakang substantif, tinjauan pustaka, metode yang akan digunakan baik metode pengumpulan data maupun metode analisis kegiatan penyusunan strategi pengawalan pertumbuhan ekonomi daerah; 2. Melakukan inventarisasi dan identifikasi indikator proxy dari sisi produksi dan sisi pengeluaran sebagai indikator pengawalan pertumbuhan ekonomi; 3. Mengawal capaian indikator proxy yang setiap bulan/triwulan rilis sebagai masukan untuk intervensi strategi dan kebijakan pengawalan pertumbuhan ekonomi; 4. Menyusun dan mempersiapkan konsep strategi pengawalan pertumbuhan ekonomi daerah kuartalan dari hasil rilis PDRB triwulanan; 5. Menyusun konsep ideal proses pengawalan pertumbuhan ekonomi daerah dengan pemangku kepentingan serta menghimpun masukan dan permasalahan yang timbul dengan merumuskan solusinya sebagai masukan penyusunan strategi pengawalan pertumbuhan ekonomi daerah; 6. Melakukan analisis kewilayahan berdasarkan potensi dan permasalahan pembangunan, keterkaitan antar wilayah, serta identifikasi sumber pertumbuhan ekonomi utama di tingkat daerah;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 84627);
