INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62798202', 62798202, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Benchmarking Kinerja Penyelenggaraan Transportasi Perkeretaapian', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1500000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Melakukan Benchmarking atau perbandingan kinerja Kinerja Penyelenggaraan Perkeretaapian terhadap indikator kinerja yang ditetapkan dari segi konektivitas (Prasarana Perkeretaapian), pelayanan (On Time Performance, Kinerja Angkutan Penumpang dan Barang serta Track Quality Indeks) dan Keselamatan yang mencakup Rasio Kejadian Kecelakaan atau jumlah kecelakaan yang terjadi', '1. Mengidentifikasi peraturan dan kajian yang terkait dengan Benchmarking Kinerja Penyelenggaraan Perkeretaapian; 2. Melakukan survei Reconnaissance dan inventarisasi data sekunder terhadap penyelenggara transportasi moda angkutan darat, laut dan udara sebagai benchmarking; 3. Mengidentifikasi dan melakukan evaluasi terhadap kinerja prasarana, sarana, keselamatan dan operasi/pelayanan transportasi Perkeretaapian kaitannnya terhadap indikator kinerja yang ditetapkan; 4. Melakukan kajian Benchmarking pada aspek Prasarana, sarana, keselamatan dan pelayanan termasuk SDM dengan kinerja pada level nasional maupun internasional; 5. Menyusun dokumen perbandingan kinerja, rekomendasi kebijakan, serta rencana aksi untuk penyempurnaan penyelenggaraan perkeretaapian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 85457);
