INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61981422', 61981422, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'LAPAS KELAS II A BINJAI', 'Pengadaan Bahan Makanan Warga Binaan Pemasyarakatan Pada Lembaga Pemasyarakatan Kelas IIA Binjai-Sumatera Utara Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'Sumatera Utara, Binjai (Kota)', 11755920000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '534360 OH', 'Menyediakan Bahan Makanan Warga Binaan Pemasyarakatan pada Lembaga Pemasyarakatan Kelas IIA Binjai selama 365 hari untuk 1.464 orang.', '1. Beras Kualitas medium, putih dan bersih, tidak berdedak, tidak berbau apek, tidak bergabah, tidak berbatu/kerikil, dan tidak terdapat kutu beras 2. Ubi/singkong Ubi yang besar, tidak busuk, segar dan bersih 3. Daging Sapi Harus berasal dari sapi yang sehat, gemuk, muda dewasa, tanpa tulang dan sedikit urat/lemak, tidak berlendir, tidak mengandung bahan pengawet, kondisi daging tidak boleh lebih dari satu hari sesudah pemotongan sapi 4. Ayam Broiler/Ras Bersih, segar muda, berat minimum 1 kg/ekor, tanpa isi, tidak suntik air, kulit belum keras dan halal 5. Ikan Kering bisa ikan kering asin atau ikan kering tawar, dengan spesifikasi kering dan bersih/tidak berjamur 6. Ikan Segar Harus segar, berkilat, kenyal tidak hancur, utuh , tidak berbau busuk dan tidak mengandung formalin 7. Telur Ayam kulit bersih, tidak retak, tidak busuk, berukuran, dalam 1 kg berisi ± 16 butir 8. Tempe Tempe kedelai berkualitas baik, tidak ada campuran, segar dan tidak busuk 9. Tahu Warna putih/kuning, segar, bersih, murni, padat, tidak hancur, mutu baik, tidak bergaram, tanpa formalin, kenyal berat minimal 50 gram 10. Kacang-kacangan Kacang Tanah : Harus kering, berisi dan bersih, terkupas, tidak berlubang, tidak berjamur dan tidak tengik Kacang Merah : Segar, utuh, bersih, tidak berakar 11. Kacang Hijau Harus kering, berisi dan bersih, tidak kisut, tidak berkutu, berwarna hijau tua, ukuran ± 4mm 12. Kelapa Daging a. (ukuran sedang, banyak santan, segar, tidak tengik dan basi, dan telah terkupas) b. Tidak boleh diganti dengan kopra; 13. Sayuran Segar Harus yang sehat, bermutu baik dan segar, terdiri dari : Daun Seledri : segar, muda, bersih, tidak berulat, tanpa akar Daun Prei/Daun Bawang : segar, muda, bersih, tidak berulat, tanpa akar, tidak berbunga, berdaun lebar Kacang Panjang : segar, muda, bersih, tidak berulat, lurus panjang dalam ikatan Kangkung : segar, muda, batang berwarna putih, tanpa akar, bersih, berdaun lebar, dalam ikatan, panjang max 30 cm Kentang Kuning : tua, segar, permukaan rata, licin, bersih, kering, 1 kg = 5-7 buah, tidak berulat Kol Putih Bandung : segar, muda, putih, bersih, padat, tidak berulat, utuh, jenis putih, minimum 750 gr/bonggol Labu Siam : segar, muda, ± 3-4 buah/kg, sudah dikupas, bersih, berat minimum 300 gr Toge Panjang : dari kacang hijau, segar, bersih, tidak busuk, batang pendek, tanpa kulit Wortel : segar, muda, bersih, tidak berdaun, tidak basah, sudah dikupas, tidak bertangkai, jenis panjang, diameter maksimum 5 cm, 1 kg = 13-14 buah Daun Ubi : segar, muda, bersih, berdaun lebar, tidak berulat Sawi Putih : segar, muda, putih, bersih, padat, tidak berulat Sawi Hijau : segar, muda, berwarna hijau, bersih, padat, tidak berulat Pepaya Muda : Segar, muda, bersih, tidak berulat 14. Buah-buahan Pisang : tua, masak, dan tidak busuk 15. Gula Kelapa/Aren Harus kering, bersih, tidak lembek dan tidak berbau 16. Gula Pasir Kering, bersih, murni, dalam negri/lokal, tidak hancur, tidak menggumpal 17. Minyak Goreng Tidak tengik, bersih, murni/tidak bercampur, dalam kemasan bersegel, tidak isi ulang (bukan minyak curah) tidak kadaluarsa, 18. Bumbu Dapur Bumbu harus terdiri dari bermacam-macam dan bumbu penyedap lainnya sesuai dengan jenis makanan yang tercantum dalam daftar menu Asam Jawa : asli, tua, dalam plastik, tidak berbiji, 500 gr/pak Bawang Putih : Kering, bersih, tua, besar merata, tidak berulat, tidak busuk Bawang Merah : Kering, bersih, tua, besar merata, tidak berulat, tidak busuk Cabe Hijau : segar, bersih, tidak berulat, tanpa batang, berwarna hijau merata Cabe Merah: segar, bersih, tidak berulat, tanpa batang, berwarna merah merata Cabe Rawit : segar, tidak busuk, berwarna hijau campur merah, tanpa batang Daun Pandan : segar bersih, tanpa akar, berwarna hijau merata Daun Salam : segar, bersih, tanpa tangkai Daun Sereh : segar, bersih Daun Jeruk Purut : segar, bersih, tanpa tangkai Jahe : segar, tua, bersih, tidak basah Kelapa Muda Parut : segar, muda terkupas, tidak tengik, tidak basi, putih, baru Kencur : segar, tua, bersih, tidak basah Kunyit : segar, tua, bersih, tidak basah Kayu Manis : batang kering, tidak berjamur Merica Giling : halus, kering, bersih, asli, 400gr/botol Terasi Udang : padat, bersih, murni, 500gr/ bks, baru, tidak berjamur, tidak mengeras, tidak apek Kemiri : putih, bersih, bulat, tidak hancur Biji Pala : coklat, bulat Ketumbar : bersih, bulat, kecil 19. Racikan Sambal Terdiri dari cabe merah segar dan cukup tua, bawang merah dan tomat 20. Garam Dapur Garam Halus : kering, bersih, berwarna putih, beryodium, tidak expire, dengan merk dan nomor register beryodium, berat 500 gr/pak Garam bata: kering, bersih, berwarna putih, beryodium, tidak expire, dengan merk dan nomor register beryodium 21. Kecap Mutu nomor 1, manis, isi 620 ml/sct, kualitas baik, tidak expire, dalam kemasan bersegel 22. Gas Gas LPG minimal 12 kg, segel utuh dan tidak rusak 23. Air Minum Air yang layak untuk diminum, lulus uji kelayakan (tersertifikasi) yang dikeluarkan oleh Dinas Kesehatan setempat (sesuai lokasi pekerjaan)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 88845);
